(function(E){ const x = E["exam-11"] = E["exam-11"] || {units:{}}; (x.units = x.units || {})["x11-r2"] = {"id":"x11-r2","patterns":["RA-mind","GT2-policy","GT2-business","PARA-research","PARA-cause","PARA-rules","TR-detail","TR-paraphrase","TR-samewords","TR-plural","TR-hedge","TR-NGvsF","TR-limit"],"title":{"en":"Reading 2: Passage 2 / Section 2","tr":"Reading 2: Passage 2 / Section 2","fa":"Reading ۲: متن ۲ (Passage 2) / بخش ۲ (Section 2)"},"objective":{"en":"After this lesson, you can find an example, a reason or a warning in lettered paragraphs, complete a summary with the passage’s own words, and answer multiple choice questions on a report about behaviour.","tr":"Bu dersin sonunda harfli paragraflarda bir örneği, bir nedeni ya da bir uyarıyı bulabilecek, bir özeti metnin kendi kelimeleriyle tamamlayabilecek ve davranış üzerine bir raporla ilgili çoktan seçmeli soruları cevaplayabileceksin.","fa":"بعد از این درس می‌توانی در پاراگراف‌های حرف‌گذاری‌شده یک مثال، یک دلیل یا یک هشدار را پیدا کنی، خلاصه را با کلمه‌های خود متن کامل کنی و به سؤال‌های چندگزینه‌ای درباره‌ی گزارشی از رفتار آدم‌ها جواب بدهی."},"objectiveGT":{"en":"After this lesson, you can decide TRUE, FALSE or NOT GIVEN on a staff guide full of conditions, and answer short questions on a service policy within the word limit.","tr":"Bu dersin sonunda koşullarla dolu bir personel rehberi hakkında TRUE, FALSE ya da NOT GIVEN’a karar verebilecek ve bir hizmet politikasıyla ilgili kısa soruları kelime sınırı içinde cevaplayabileceksin.","fa":"بعد از این درس می‌توانی درباره‌ی یک راهنمای کارکنان که پر از شرط است بین ⁨TRUE⁩، ⁨FALSE⁩ و ⁨NOT GIVEN⁩ تصمیم بگیری و به سؤال‌های کوتاه درباره‌ی یک آیین‌نامه‌ی خدمات در محدوده‌ی سقف کلمه جواب بدهی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Reading Passage 2: a report on everyday behaviour","tr":"Reading Passage 2: gündelik davranış üzerine bir rapor","fa":"Reading Passage 2: گزارشی درباره‌ی رفتارهای روزمره"},"objective":{"en":"After this lesson, you can find an example, a reason or a warning in lettered paragraphs, complete a summary with the passage’s own words, and answer multiple choice questions on a report about behaviour.","tr":"Bu dersin sonunda harfli paragraflarda bir örneği, bir nedeni ya da bir uyarıyı bulabilecek, bir özeti metnin kendi kelimeleriyle tamamlayabilecek ve davranış üzerine bir raporla ilgili çoktan seçmeli soruları cevaplayabileceksin.","fa":"بعد از این درس می‌توانی در پاراگراف‌های حرف‌گذاری‌شده یک مثال، یک دلیل یا یک هشدار را پیدا کنی، خلاصه را با کلمه‌های خود متن کامل کنی و به سؤال‌های چندگزینه‌ای درباره‌ی گزارشی از رفتار آدم‌ها جواب بدهی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"13"},{"label":{"en":"Paragraphs","tr":"Paragraf","fa":"پاراگراف"},"value":"A-G"},{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"20 min","tr":"20 dk","fa":"۲۰ دقیقه"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ زمینه"},"head":{"en":"This exam: the psychology of queuing","tr":"Bu sınav: sıra beklemenin psikolojisi","fa":"این آزمون: روان‌شناسیِ صف کشیدن"},"intro":{"en":"Psychology and everyday behaviour are among the most frequent Academic topics. Passage 2 is often a report in lettered paragraphs that moves from research to practical uses, so the paragraph questions test details hidden inside paragraphs about something else.","tr":"Psikoloji ve gündelik davranış en sık çıkan Academic konular arasındadır. Passage 2 çoğu zaman araştırmadan pratik uygulamalara geçen, harfli paragraflardan oluşan bir rapordur; bu yüzden paragraf soruları, başka bir konuyu anlatan paragrafların içine gizlenmiş ayrıntıları sınar.","fa":"روان‌شناسی و رفتارهای روزمره از پرتکرارترین موضوع‌های ⁨Academic⁩ هستند. ⁨Passage 2⁩ اغلب گزارشی با پاراگراف‌های حرف‌گذاری‌شده است که از پژوهش به کاربردهای عملی می‌رسد، برای همین سؤال‌های پاراگراف جزئیاتی را می‌سنجند که وسط پاراگرافی درباره‌ی موضوعی دیگر پنهان شده‌اند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب در آن‌هاست"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x11-r2-ctx","exam":true,"patterns":["RA-mind","PARA-research","PARA-cause"],"often":{"pattern":"RA-mind","n":30,"of":120,"label":{"en":"Comes up often in the real exam: 30 of the last 120 passages","tr":"Gerçek sınavda sık çıkar: son 120 metnin 30’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۳۰ متن از ۱۲۰ متنِ اخیر"}},"title":{"en":"How people experience waiting","tr":"İnsanlar beklemeyi nasıl yaşar","fa":"آدم‌ها انتظار را چطور تجربه می‌کنند"},"asks":{"en":"A report in seven lettered paragraphs on everyday behaviour: why some waits feel longer than others, why fairness matters so much, and how banks and theme parks design their queues. It names researchers and gives short examples from lifts, airports and telephone helplines.","tr":"Gündelik davranış üzerine yedi harfli paragraftan oluşan bir rapor: Bazı beklemeler neden diğerlerinden uzun gelir, adalet neden bu kadar önemlidir, bankalar ve eğlence parkları sıralarını nasıl tasarlar? Araştırmacıların adını verir; asansörlerden, havalimanlarından ve telefon destek hatlarından kısa örnekler sunar.","fa":"گزارشی در هفت پاراگراف حرف‌گذاری‌شده درباره‌ی رفتار روزمره: چرا بعضی انتظارها طولانی‌تر به نظر می‌رسند، چرا انصاف این‌قدر مهم است و بانک‌ها و پارک‌های تفریحی صف‌هایشان را چطور طراحی می‌کنند. اسم پژوهشگرها را می‌آورد و مثال‌های کوتاهی از آسانسور، فرودگاه و خط‌های تلفنی پشتیبانی می‌زند."},"fields":["Idle time","Not knowing","Fairness","One line or many","Theme parks","What works best"],"words":[{"a":"an example","b":"in a story that is often repeated / in one case","tr":"bir örnek","fa":"یک مثال"},{"a":"reduced complaints","b":"the complaints stopped / fell sharply","tr":"şikâyetleri azalttı","fa":"شکایت‌ها را کم کرد"},{"a":"with nothing to do","b":"unoccupied / idle","tr":"yapacak bir şey olmadan","fa":"بی‌کار، بی‌سرگرمی"},{"a":"more patient","b":"more willing to stay on the line","tr":"daha sabırlı","fa":"صبورتر"},{"a":"how likely","b":"the chance that / one in three","tr":"ne kadar olası","fa":"چقدر احتمال دارد"},{"a":"people behind","b":"those directly behind / further back","tr":"arkadakiler","fa":"آدم‌های پشت سر"},{"a":"unfair","b":"pushing in / jumping the queue","tr":"adaletsiz","fa":"ناعادلانه"},{"a":"deliberately","b":"on purpose","tr":"kasten","fa":"عمداً"},{"a":"feel pleased","b":"feel that they have gained something","tr":"memnun olmak","fa":"خوشحال شدن"},{"a":"by paying","b":"visitors who pay extra","tr":"para ödeyerek","fa":"با پرداخت پول"},{"a":"discourage","b":"persuade people not to","tr":"vazgeçirmek","fa":"دلسرد کردن"},{"a":"a warning","b":"specialists warn / may backfire","tr":"bir uyarı","fa":"یک هشدار"}],"traps":[{"en":"Paragraph questions: the answer is one sentence, not the paragraph's topic. A story about a shop can sit inside a paragraph about prices.","tr":"Paragraf soruları: Cevap paragrafın konusu değil, tek bir cümledir. Bir dükkânla ilgili hikâye, fiyatlar üzerine bir paragrafın içinde olabilir.","fa":"سؤال‌های پاراگراف: جواب یک جمله است، نه موضوع کل پاراگراف. ماجرایی درباره‌ی یک مغازه ممکن است وسط پاراگرافی درباره‌ی قیمت‌ها باشد."},{"en":"The same words can appear in two paragraphs. Match the idea in the question, not a phrase you recognise.","tr":"Aynı kelimeler iki paragrafta geçebilir. Tanıdığın bir ifadeyi değil, sorudaki fikri eşleştir.","fa":"ممکن است همان کلمه‌ها در دو پاراگراف بیایند. ایده‌ی سؤال را جور کن، نه عبارتی را که آشنا به نظر می‌رسد."},{"en":"Summary: copy the passage's own word. A synonym you know, such as \"clients\" for \"customers\", is marked wrong.","tr":"Özet: Metnin kendi kelimesini kopyala. Bildiğin bir eş anlamlı, örneğin \"customers\" yerine \"clients\", yanlış sayılır.","fa":"خلاصه: همان کلمه‌ی متن را کپی کن. مترادفی که بلدی، مثلاً «⁨clients⁩» به‌جای «⁨customers⁩»، غلط حساب می‌شود."}],"example":{"text":"\"C  Waits are common in hospitals, where demand is high and staff are few.  D  In one hospital, a screen showing expected waiting times made patients calmer, although the waits were as long as before.\"","item":"Which paragraph contains an example of information changing how people felt?","answer":"D","why":{"en":"C explains why waits are common; the example (a screen, calmer patients) is in D.","tr":"C beklemelerin neden yaygın olduğunu açıklıyor; örnek (bir ekran, daha sakin hastalar) D’de.","fa":"⁨C⁩ توضیح می‌دهد چرا انتظار رایج است؛ مثال (یک صفحه‌ی نمایش و بیمارهای آرام‌تر) در ⁨D⁩ است."}}},{"id":"RA-mind-report","ctx":["RA-mind"],"title":{"en":"Reports on learning, the mind and society","tr":"Öğrenme, zihin ve toplum üzerine raporlar","fa":"گزارش درباره‌ی یادگیری، ذهن و جامعه"},"asks":{"en":"A report on how people learn, think or behave: bilingual children, boredom, play, mixed-ability classes, putting things off. Paragraphs describe research, explanations and practical advice.","tr":"İnsanların nasıl öğrendiği, düşündüğü ya da davrandığı üzerine bir rapor: iki dilli çocuklar, can sıkıntısı, oyun, karma düzeyli sınıflar, işleri erteleme. Paragraflar araştırmaları, açıklamaları ve pratik tavsiyeleri anlatır.","fa":"گزارشی درباره‌ی اینکه آدم‌ها چطور یاد می‌گیرند، فکر می‌کنند یا رفتار می‌کنند: بچه‌های دوزبانه، کسالت، بازی، کلاس‌های چندسطحی، عقب انداختن کارها. پاراگراف‌ها پژوهش‌ها، توضیح‌ها و توصیه‌های کاربردی را شرح می‌دهند."},"fields":["A popular belief challenged","The benefits for older learners","A practical suggestion for teachers","How the research was carried out","Which paragraph mentions the age of the participants?"],"words":[{"a":"a common belief","b":"many people assume / it is widely thought","tr":"yaygın bir inanış","fa":"باوری رایج"},{"a":"challenge","b":"question / cast doubt on","tr":"sorgulamak","fa":"زیر سؤال بردن"},{"a":"evidence","b":"studies show / data suggest","tr":"kanıt","fa":"شواهد"},{"a":"advantage","b":"benefit / gain","tr":"avantaj","fa":"مزیت"},{"a":"practical advice","b":"tips / what teachers can do","tr":"pratik tavsiye","fa":"توصیه‌ی کاربردی"},{"a":"lasting effect","b":"years later / long-term","tr":"kalıcı etki","fa":"اثر ماندگار"},{"a":"participants","b":"volunteers / subjects","tr":"katılımcılar","fa":"شرکت‌کننده‌ها"},{"a":"age group","b":"children aged six to nine","tr":"yaş grubu","fa":"گروه سنی"},{"a":"behaviour","b":"what people do / how they act","tr":"davranış","fa":"رفتار"},{"a":"motivation","b":"the reason people try","tr":"motivasyon","fa":"انگیزه"},{"a":"concentration","b":"focus / attention","tr":"dikkat","fa":"تمرکز"},{"a":"the role of","b":"how ... contributes to","tr":"... -in rolü","fa":"نقشِ"}],"traps":[{"en":"A heading that repeats a word from the paragraph is often wrong. Match the idea, not the word.","tr":"Paragraftaki bir kelimeyi tekrarlayan başlık çoğu zaman yanlıştır. Kelimeyi değil, fikri eşleştir.","fa":"عنوانی که یک کلمه‌ی پاراگراف را تکرار می‌کند اغلب غلط است. ایده را جور کن، نه کلمه را."},{"en":"Matching information can use the same letter twice: one paragraph may answer two questions.","tr":"Bilgi eşleştirmede aynı harf iki kez kullanılabilir: bir paragraf iki soruyu cevaplayabilir.","fa":"در جورکردن اطلاعات یک حرف ممکن است دو بار بیاید: یک پاراگراف می‌تواند جواب دو سؤال باشد."}],"example":{"text":"B  It is often said that boredom is simply a waste of time. Recent work suggests the opposite: people who did a dull task before a creative one produced more original ideas than those who went straight to the creative task.","item":"Choose the heading for paragraph B:  i  A popular view of boredom questioned   ii  Ways to avoid boredom at work   iii  Why creative tasks are dull","answer":"i","why":{"en":"\"It is often said... Recent work suggests the opposite\" = a common belief challenged.","tr":"\"Sık söylenir... Yeni çalışmalar tersini gösteriyor\" = sorgulanan yaygın bir inanış.","fa":"«اغلب گفته می‌شود... پژوهش‌های تازه خلافش را نشان می‌دهند» یعنی باوری رایج که زیر سؤال رفته."}},"track":"academic","general":true,"patterns":["RA-mind"],"often":{"pattern":"RA-mind","n":30,"of":120,"label":{"en":"Comes up often in the real exam: 30 of the last 120 passages","tr":"Gerçek sınavda sık çıkar: son 120 metnin 30’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۳۰ متن از ۱۲۰ متنِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Paragraphs, a summary, four choices","tr":"Paragraflar, bir özet, dört seçenek","fa":"پاراگراف‌ها، یک خلاصه، چهار گزینه"},"body":{"en":"Questions 14-18: which paragraph, A-G, contains each piece of information; some letters are not used. Questions 19-22: complete a summary with ONE WORD ONLY from the passage. Questions 23-26: choose A, B, C or D.","tr":"Soru 14-18: Her bilgi hangi paragrafta (A-G)? Bazı harfler kullanılmaz. Soru 19-22: bir özeti metinden YALNIZCA BİR KELİMEYLE tamamla. Soru 23-26: A, B, C ya da D’yi seç.","fa":"سؤال‌های ۱۴ تا ۱۸: هر نکته در کدام پاراگراف (⁨A⁩ تا ⁨G⁩) است؛ بعضی حرف‌ها استفاده نمی‌شوند. سؤال‌های ۱۹ تا ۲۲: خلاصه را فقط با یک کلمه از متن کامل کن. سؤال‌های ۲۳ تا ۲۶: ⁨A⁩، ⁨B⁩، ⁨C⁩ یا ⁨D⁩ را انتخاب کن."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps","tr":"Dört adım","fa":"چهار قدم"},"steps":[{"en":"Turn each piece of information into a type of sentence to look for: an example, a reason, a warning, research.","tr":"Her bilgiyi aranacak bir cümle türüne çevir: bir örnek, bir neden, bir uyarı, bir araştırma.","fa":"هر نکته را به نوعی جمله تبدیل کن که باید دنبالش بگردی: یک مثال، یک دلیل، یک هشدار، یک پژوهش."},{"en":"Do the summary and the multiple choice first: they follow the passage order and show you where things are.","tr":"Önce özeti ve çoktan seçmeli soruları yap: Metnin sırasını izlerler ve neyin nerede olduğunu gösterirler.","fa":"اول خلاصه و چندگزینه‌ای‌ها را حل کن: به ترتیب متن‌اند و نشانت می‌دهند هر چیز کجاست."},{"en":"For the summary, find the paragraph, then copy the word the passage uses, in the form the gap needs.","tr":"Özet için paragrafı bul, sonra metnin kullandığı kelimeyi boşluğun gerektirdiği biçimde kopyala.","fa":"برای خلاصه پاراگراف را پیدا کن و بعد همان کلمه‌ای را که متن به کار برده، به شکلی که جای خالی لازم دارد، کپی کن."},{"en":"Match the paragraphs last, sentence by sentence; a letter may be used twice or not at all.","tr":"Paragrafları en sona bırak ve cümle cümle eşleştir; bir harf iki kez kullanılabilir ya da hiç kullanılmayabilir.","fa":"جور کردن پاراگراف‌ها را آخر انجام بده، جمله به جمله؛ ممکن است یک حرف دو بار بیاید یا اصلاً نیاید."}],"wrong":"Organisations would like their clients to wait more happily.","right":"Organisations would like their customers to wait more happily.","tip":{"en":"Why it works: a summary checks that you found the passage's own word. \"Clients\" means much the same, but it is not in the passage, so it is marked wrong. Persian and Turkish use one word for both, so check which English word the text actually uses.","tr":"Neden işe yarar: Özet, metnin kendi kelimesini bulup bulmadığını ölçer. \"Clients\" hemen hemen aynı anlama gelir ama metinde geçmez, bu yüzden yanlış sayılır. Türkçede ikisi için de tek kelime var (müşteri), o yüzden metnin hangi İngilizce kelimeyi kullandığına bak.","fa":"این روش به کارت می‌آید، چون خلاصه می‌سنجد که خود کلمه‌ی متن را پیدا کرده‌ای یا نه. «⁨clients⁩» تقریباً همان معنی را دارد، اما در متن نیامده و برای همین غلط حساب می‌شود. در فارسی برای هر دو یک کلمه داریم («مشتری»)، پس ببین متن دقیقاً کدام کلمه‌ی انگلیسی را به کار برده."}},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Question words point to a type of sentence","tr":"Soru kelimeleri bir cümle türünü gösterir","fa":"کلمه‌های سؤال نوع جمله را نشان می‌دهند"},"table":{"headers":{"en":["In the question","Look for"],"tr":["Soruda","Şunu ara"],"fa":["در سؤال","دنبال این بگرد"]},"rows":[["an example of","in one case / in a story / in one hospital"],["a reason why","because / since / this is why"],["a warning","may backfire / the risk is / specialists warn"],["research showing","studies have found / researchers found"]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One paragraph match, step by step","tr":"Bir paragraf eşleştirmesi, adım adım","fa":"جور کردن یک پاراگراف، قدم به قدم"},"instruction":"Which paragraph contains the following information?","text":"\"A  Supermarkets have long tried to reduce queues at the tills.  B  When one store added a screen showing the next free till, customers chose tills faster and complaints fell.\"","item":"Information: an example of a change that made customers happier","answer":"B","walk":[{"en":"The type of sentence: an example of a change, with its result.","tr":"Cümle türü: bir değişiklik örneği ve sonucu.","fa":"نوع جمله: مثالی از یک تغییر، همراه با نتیجه‌اش."},{"en":"A describes a general aim; it gives no example.","tr":"A genel bir amaçtan söz ediyor; örnek vermiyor.","fa":"⁨A⁩ یک هدف کلی را می‌گوید و مثالی نمی‌زند."},{"en":"B: \"one store added a screen... complaints fell\" is an example of a change: B.","tr":"B: \"bir mağaza bir ekran ekledi... şikâyetler azaldı\" bir değişiklik örneğidir: B.","fa":"⁨B⁩: «یک فروشگاه یک صفحه‌ی نمایش اضافه کرد... شکایت‌ها کم شد» مثالی از یک تغییر است: ⁨B⁩."}]},"quick":{"prompt":"Paragraph: \"Queues at the post office were once a daily complaint. In 1998, one branch tried a single line for all its counters.\" Which information does it contain?","options":["an example of a new arrangement","a reason why queues are fair","a warning about costs"],"correct":0,"why":{"en":"\"One branch tried a single line\" is one case: an example of a new arrangement.","tr":"\"Bir şube tek bir sıra denedi\" tek bir vakadır: yeni bir düzenleme örneği.","fa":"«یک شعبه صف واحد را امتحان کرد» یک مورد مشخص است: مثالی از یک ترتیب تازه."}},"remember":{"en":"Look for the type of sentence the question describes, and copy summary words from the passage itself. Result: you can now find details in lettered paragraphs and complete a summary with the passage's own words.","tr":"Sorunun tarif ettiği cümle türünü ara ve özet kelimelerini doğrudan metinden kopyala. Sonuç: Artık harfli paragraflarda ayrıntıları bulabilir, bir özeti metnin kendi kelimeleriyle tamamlayabilirsin.","fa":"دنبال همان نوع جمله‌ای بگرد که سؤال توصیف می‌کند و کلمه‌های خلاصه را از خود متن کپی کن. نتیجه: حالا می‌توانی جزئیات را در پاراگراف‌های حرف‌گذاری‌شده پیدا کنی و خلاصه را با کلمه‌های خود متن کامل کنی."},"hook":{"en":"This Passage 2 explains why waiting feels the way it does. The main idea: an example, a reason or a warning can sit inside any paragraph, so look for the type of sentence, not the topic.","tr":"Bu Passage 2 beklemenin neden öyle hissettirdiğini açıklar. Ana fikir: Bir örnek, bir neden ya da bir uyarı herhangi bir paragrafın içinde olabilir; konuyu değil, cümle türünü ara.","fa":"این ⁨Passage 2⁩ توضیح می‌دهد چرا انتظار این‌طور حس می‌شود. مثال، دلیل یا هشدار ممکن است در هر پاراگرافی باشد، پس دنبال نوع جمله بگرد، نه موضوع."},"type":"explain","id":"c-x11-r2-e","course":"ielts-exams","exam":"exam-11","unit":"x11-r2"},"drill":{"type":"drill","skill":"reading","part":"Academic Reading Passage 2","title":{"en":"Why waiting feels the way it does","tr":"Beklemek neden öyle hissettirir","fa":"چرا انتظار این‌طور حس می‌شود"},"timed":20,"ctx":["RA-mind"],"intro":"You should spend about 20 minutes on Questions 14-26, which are based on Reading Passage 2 below.","passage":"Why waiting feels the way it does\n\nA  Few people enjoy queuing, yet most of us do it every day: at supermarket tills, at bus stops, on the telephone and, increasingly, in online waiting rooms for concert tickets. What is less obvious is that two waits of exactly the same length can feel very different. A ten-minute delay can pass almost unnoticed or seem to last for ever, depending on the circumstances. Over the past forty years, psychologists and specialists in the management of services have tried to explain why, and their findings are now used by organisations that would like their customers to wait more happily, even when they cannot make them wait less.\n\nB  A useful starting point is a short paper published in 1985 by the business researcher David Maister, who set out a number of principles of waiting. The first was that unoccupied time feels longer than occupied time. In a story that is often repeated, the managers of a tall office building, faced with complaints about slow lifts, placed large mirrors beside the lift doors. People now had something to look at while they waited, mainly themselves, and the complaints stopped, although the lifts were no faster. A similar idea was used at an airport where passengers complained about the wait for their luggage. Instead of speeding up the baggage handling, the airport moved the arrival gates further from the luggage hall. Passengers now spent most of the time walking rather than standing, and complaints fell sharply.\n\nC  Maister also argued that uncertain waits feel longer than known ones, and that unexplained waits feel longer than explained ones. A delay of twenty minutes is far easier to bear if the pilot announces it, together with the reason, than if passengers simply sit on the runway in silence. Studies of telephone helplines have found that callers who are told their position in the queue, or how long they are likely to wait, are more willing to stay on the line than callers who hear only music. Anxiety has a similar effect. A traveller who is anxious about missing a connecting flight will experience a short queue at passport control as much longer than a relaxed traveller does, because every glance at the clock makes the delay seem worse.\n\nD  Many researchers believe, however, that what upsets people most is not the length of a wait but its fairness. In the 1960s, the Australian psychologist Leon Mann studied crowds who queued overnight for football tickets in Melbourne and found that the queues worked like small societies, with their own rules. People were allowed to leave for short periods, for example, as long as they had arranged with their neighbours to keep their place. Pushing in, on the other hand, caused real anger. Two decades later, researchers working with the social psychologist Stanley Milgram sent assistants to push into queues in New York. Objections came most often from the people standing directly behind the intruder, who had actually lost time; those further ahead, who had lost nothing, rarely said a word.\n\nE  This concern with fairness helps to explain one of the most common changes in queue design. Banks and post offices in many countries have replaced separate lines in front of each counter with a single winding queue that feeds all the counters. On average, customers in a single queue wait no longer than they would in separate lines, and often less, but the main advantage lies elsewhere: no one can be stuck behind a slow customer while the next line races ahead. With separate lines, frustration is almost built in. If there are three lines, the chance that yours will be the fastest is only one in three, which is why it so often seems that another queue is moving more quickly. Even so, single queues are not always popular. Because they gather everyone in one place, they can look alarmingly long, and some shops have kept separate lines for this reason.\n\nF  Theme parks have taken queue design further than anyone. Their queues are built to wind back and forth, so visitors rarely see how far they still have to go, and long sections are placed inside buildings decorated to tell the story of the ride, so that the wait itself becomes part of the entertainment. Many parks are also said to display waiting times that are deliberately a little longer than they expect. Visitors who are told they will wait forty-five minutes and reach the front in thirty-five feel that they have gained something. More recently, many parks have introduced virtual queues, in which visitors book a time on an app and return later. These have made parks more pleasant, but critics point out that some systems allow visitors who pay extra to skip most of the queue, which other visitors understandably see as unfair.\n\nG  Not every lesson from this research involves gentle deception. Some specialists warn that such tricks can backfire if customers notice them: a waiting time that is regularly much too pessimistic, for example, may persuade people not to join the queue at all. The most reliable principles may also be the simplest. Tell people how long they will wait and why, give them something to do, and make sure that whoever arrives first is served first. A queue that follows these rules may still be long, but it is far less likely to leave people angry.","groups":[{"instruction":"Questions 14-18. Reading Passage 2 has seven paragraphs, A-G. Which paragraph contains the following information? Write the correct letter, A-G, in boxes 14-18 on your answer sheet. NB You may use any letter more than once.","qtype":"match-info","bank":["A","B","C","D","E","F","G"],"questions":[{"n":14,"kind":"match","prompt":"an example of a change that reduced complaints without making a wait shorter","correct":1,"evidence":"the complaints stopped, although the lifts were no faster","why":{"en":"B: after the mirrors were put up, \"the complaints stopped, although the lifts were no faster\".","tr":"B: aynalar konduktan sonra \"asansörler hızlanmadığı hâlde şikâyetler kesildi\".","fa":"⁨B⁩: بعد از گذاشتن آینه‌ها «شکایت‌ها قطع شد، با اینکه آسانسورها سریع‌تر نشده بودند»."},"trap":["TR-detail","TR-paraphrase"]},{"n":15,"kind":"match","prompt":"a reference to how likely it is that a person chooses the quickest line","correct":4,"evidence":"the chance that yours will be the fastest is only one in three","why":{"en":"E: with three lines, \"the chance that yours will be the fastest is only one in three\".","tr":"E: Üç sıra varsa \"seninkinin en hızlısı olma ihtimali yalnızca üçte bir\".","fa":"⁨E⁩: با سه صف «احتمال اینکه صف تو سریع‌ترین باشد فقط یک‌سوم است»."},"trap":["TR-paraphrase"]},{"n":16,"kind":"match","prompt":"a description of how people's reactions depend on their position in a queue","correct":3,"evidence":"Objections came most often from the people standing directly behind the intruder","why":{"en":"D: objections came from people \"directly behind the intruder\"; those further ahead \"rarely said a word\". C also mentions a \"position in the queue\", but not reactions.","tr":"D: İtirazlar \"araya girenin hemen arkasındakilerden\" geldi; öndekiler \"neredeyse hiç ses çıkarmadı\". C de \"sıradaki yer\"den söz ediyor ama tepkilerden değil.","fa":"⁨D⁩: اعتراض‌ها از کسانی بود که «درست پشت سرِ کسی که وسط صف پریده» ایستاده بودند و جلویی‌ها «تقریباً هیچ نگفتند». ⁨C⁩ هم از «جای آدم در صف» حرف می‌زند، اما نه از واکنش‌ها."},"trap":["TR-detail","TR-samewords"]},{"n":17,"kind":"match","prompt":"a warning that a technique may discourage people from waiting","correct":6,"evidence":"may persuade people not to join the queue at all","why":{"en":"G: a waiting time that is \"regularly much too pessimistic... may persuade people not to join the queue at all\".","tr":"G: Sürekli fazla karamsar bir bekleme süresi \"insanları sıraya hiç girmemeye ikna edebilir\".","fa":"⁨G⁩: زمان انتظاری که مدام بیش از حد بدبینانه باشد «ممکن است آدم‌ها را قانع کند اصلاً در صف نایستند»."},"trap":["TR-paraphrase"]},{"n":18,"kind":"match","prompt":"research showing that information can make people more willing to wait","correct":2,"evidence":"are more willing to stay on the line than callers who hear only music","why":{"en":"C: callers told their position or waiting time \"are more willing to stay on the line than callers who hear only music\".","tr":"C: Sıradaki yerini ya da bekleme süresini öğrenen arayanlar \"yalnızca müzik dinleyenlerden daha istekli biçimde hatta kalıyor\".","fa":"⁨C⁩: تماس‌گیرنده‌هایی که جایشان در صف یا زمان انتظار را می‌دانند «بیشتر از کسانی که فقط موسیقی می‌شنوند حاضرند پشت خط بمانند»."},"trap":["TR-paraphrase"]}]},{"instruction":"Questions 19-22. Complete the summary below. Choose ONE WORD ONLY from the passage for each answer. Write your answers in boxes 19-22 on your answer sheet.","qtype":"summary","summaryTitle":"Why some waits feel longer","questions":[{"n":19,"kind":"gap","prompt":"Time spent with nothing to do seems to pass more slowly than time that is ___.","accept":["occupied"],"limit":1,"evidence":"unoccupied time feels longer than occupied time","why":{"en":"\"Unoccupied time feels longer than occupied time\". \"Unoccupied\" is the opposite, and \"busy\" is not in the passage.","tr":"\"Boş geçen zaman, meşgul geçen zamandan daha uzun gelir\". \"Unoccupied\" tam tersidir, \"busy\" ise metinde yok.","fa":"«وقتِ بیکاری طولانی‌تر از وقتی حس می‌شود که سرت گرم است». «⁨unoccupied⁩» برعکس است و «⁨busy⁩» در متن نیامده."},"trap":["TR-paraphrase","TR-samewords"]},{"n":20,"kind":"gap","prompt":"In one story, people stopped complaining after mirrors were put beside some slow ___.","accept":["lifts"],"limit":1,"evidence":"faced with complaints about slow lifts","why":{"en":"\"Complaints about slow lifts... placed large mirrors beside the lift doors\". Plural: \"lift\" is wrong.","tr":"\"Yavaş asansörlerle ilgili şikâyetler... asansör kapılarının yanına büyük aynalar kondu\". Çoğul: \"lift\" yanlış olur.","fa":"«شکایت از آسانسورهای کُند... کنار درهای آسانسور آینه‌های بزرگ گذاشتند». جمع است: «⁨lift⁩» غلط است."},"trap":["TR-plural"]},{"n":21,"kind":"gap","prompt":"A delay is easier to accept if people are told the ___ for it.","accept":["reason"],"limit":1,"evidence":"together with the reason","why":{"en":"A delay is easier to bear if the pilot announces it, \"together with the reason\".","tr":"Pilot gecikmeyi \"nedeniyle birlikte\" duyurursa gecikmeye katlanmak çok daha kolaydır.","fa":"اگر خلبان تأخیر را «همراه با دلیلش» اعلام کند، تحمل آن خیلی راحت‌تر است."},"trap":["TR-paraphrase"]},{"n":22,"kind":"gap","prompt":"Waits also seem longer to people who are ___, such as travellers who may miss a flight.","accept":["anxious"],"limit":1,"evidence":"A traveller who is anxious about missing a connecting flight","why":{"en":"\"A traveller who is anxious about missing a connecting flight\". The gap needs the adjective \"anxious\", not the noun \"anxiety\".","tr":"\"Aktarmalı uçağını kaçırmaktan endişe eden bir yolcu\". Boşluk \"anxiety\" ismini değil, \"anxious\" sıfatını ister.","fa":"«مسافری که نگرانِ از دست دادن پرواز بعدی‌اش است». جای خالی صفت «⁨anxious⁩» را می‌خواهد، نه اسم «⁨anxiety⁩» را."},"trap":["TR-paraphrase","TR-samewords"]}]},{"instruction":"Questions 23-26. Choose the correct letter, A, B, C or D. Write the correct letter in boxes 23-26 on your answer sheet.","qtype":"mcq","questions":[{"n":23,"kind":"mcq","prompt":"What does the writer say about single queues in banks and post offices?","options":["A Customers always wait less than in separate lines.","B Their main benefit is that they treat customers fairly.","C Most customers prefer the way they look.","D They were first introduced by shops."],"correct":1,"evidence":"no one can be stuck behind a slow customer while the next line races ahead","why":{"en":"The main advantage is that \"no one can be stuck behind a slow customer\": fairness. Customers wait \"no longer... and often less\", not always less.","tr":"Asıl avantaj, \"kimsenin yavaş bir müşterinin arkasında takılıp kalmaması\": adalet. Müşteriler \"daha uzun değil, çoğu zaman daha kısa\" bekler; her zaman daha kısa değil.","fa":"مزیت اصلی این است که «هیچ‌کس پشت مشتری کُند گیر نمی‌کند»: یعنی انصاف. مشتری‌ها «بیشتر منتظر نمی‌مانند و اغلب کمتر»، نه همیشه کمتر."},"trap":["TR-paraphrase","TR-samewords"]},{"n":24,"kind":"mcq","prompt":"Why do many theme parks display waiting times that are longer than they expect?","options":["A to stop too many visitors joining the queue","B because the rides often break down","C to encourage visitors to use the app","D so that visitors feel pleased when they wait less"],"correct":3,"evidence":"reach the front in thirty-five feel that they have gained something","why":{"en":"Visitors who reach the front sooner than they were told \"feel that they have gained something\".","tr":"Söylenenden önce öne ulaşan ziyaretçiler \"bir şey kazanmış gibi hisseder\".","fa":"بازدیدکننده‌هایی که زودتر از زمان اعلام‌شده به جلوی صف می‌رسند «احساس می‌کنند چیزی به دست آورده‌اند»."},"trap":["TR-paraphrase"]},{"n":25,"kind":"mcq","prompt":"What criticism of virtual queues does the writer mention?","options":["A They can let some visitors avoid long waits by paying more.","B They are difficult to use without a phone.","C They make the rides less exciting.","D They cost parks more to run than ordinary queues."],"correct":0,"evidence":"some systems allow visitors who pay extra to skip most of the queue","why":{"en":"Critics say some systems \"allow visitors who pay extra to skip most of the queue\", which others see as unfair.","tr":"Eleştirmenlere göre bazı sistemler \"fazladan ödeyen ziyaretçilerin sıranın çoğunu atlamasına izin veriyor\"; diğerleri bunu haksız buluyor.","fa":"منتقدها می‌گویند بعضی سیستم‌ها «به بازدیدکننده‌هایی که پول بیشتری می‌دهند اجازه می‌دهند بیشتر صف را دور بزنند» و بقیه این را ناعادلانه می‌دانند."},"trap":["TR-paraphrase"]},{"n":26,"kind":"mcq","prompt":"What is the writer's main point in the final paragraph?","options":["A Businesses should never use psychological tricks.","B Customers are easily fooled by clever queue design.","C Honest information and a fair order matter most.","D Technology will soon make queues unnecessary."],"correct":2,"evidence":"Tell people how long they will wait and why","why":{"en":"The simplest principles: tell people how long and why, give them something to do, and serve whoever arrives first. A is too strong: the writer only warns that tricks can backfire.","tr":"En basit ilkeler: İnsanlara ne kadar ve neden bekleyeceklerini söyle, onlara yapacak bir şey ver ve ilk gelene ilk hizmeti ver. A fazla güçlü: Yazar yalnızca hilelerin ters tepebileceği konusunda uyarıyor.","fa":"ساده‌ترین اصل‌ها: به آدم‌ها بگو چقدر و چرا منتظر می‌مانند، سرشان را گرم کن و هر کس اول آمد اول راهش بینداز. گزینه‌ی ⁨A⁩ زیادی تند است: نویسنده فقط هشدار می‌دهد که این ترفندها ممکن است نتیجه‌ی عکس بدهند."},"trap":["TR-paraphrase","TR-hedge"]}]}],"id":"c-x11-r2-d","course":"ielts-exams","exam":"exam-11","unit":"x11-r2"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"Unoccupied time feels longer than occupied time.\" Unoccupied time is time when you...","options":["have nothing to do","are with other people","are in a hurry"],"correct":0,"why":{"en":"Unoccupied = not busy, with nothing to fill the time.","tr":"Unoccupied = meşgul olmayan, zamanı dolduracak bir şey olmayan.","fa":"⁨unoccupied⁩ یعنی بی‌کار، بدون چیزی که وقت را پر کند."}},{"tests":"paraphrase","point":1,"prompt":"A question says \"discourage people from waiting\". Which phrase in a passage could match it?","options":["may persuade people not to join the queue","makes the wait part of the entertainment","whoever arrives first is served first"],"correct":0,"why":{"en":"Persuade people not to join = discourage them from waiting.","tr":"İnsanları sıraya girmemeye ikna etmek = onları beklemekten vazgeçirmek.","fa":"«آدم‌ها را قانع کند در صف نایستند» یعنی آن‌ها را از انتظار دلسرد کند."}},{"tests":"method","point":2,"prompt":"A question asks for \"an example of a change\". What should you look for?","options":["the word \"example\" in a paragraph","a sentence about one case, such as \"one store\" or \"in one story\"","the first sentence of each paragraph"],"correct":1,"why":{"en":"An example is usually one case described in a sentence; the word \"example\" itself is often missing.","tr":"Örnek genelde bir cümlede anlatılan tek bir vakadır; \"example\" kelimesinin kendisi çoğu zaman geçmez.","fa":"مثال معمولاً یک مورد مشخص است که در یک جمله آمده؛ خود کلمه‌ی «⁨example⁩» اغلب در متن نیست."}},{"tests":"trap","point":3,"prompt":"A summary reads \"...than time that is ___\" (ONE WORD ONLY). The passage says \"unoccupied time feels longer than occupied time\". Which answer is right?","options":["busy","unoccupied","occupied"],"correct":2,"why":{"en":"The meaning needs \"occupied\"; \"busy\" is not in the passage, and \"unoccupied\" is the opposite.","tr":"Anlam \"occupied\" gerektiriyor; \"busy\" metinde yok, \"unoccupied\" ise tam tersi.","fa":"معنی «⁨occupied⁩» را می‌خواهد؛ «⁨busy⁩» در متن نیست و «⁨unoccupied⁩» برعکسش است."}}],"id":"c-x11-r2-x","course":"ielts-exams","exam":"exam-11","unit":"x11-r2"},"gt":{"explain":{"title":{"en":"GT Reading Section 2: a staff rota and a service policy","tr":"GT Reading Section 2: bir vardiya çizelgesi ve bir hizmet politikası","fa":"GT Reading Section 2: برنامه‌ی شیفت و آیین‌نامه‌ی خدمات"},"objective":{"en":"After this lesson, you can decide TRUE, FALSE or NOT GIVEN on a staff guide full of conditions, and answer short questions on a service policy within the word limit.","tr":"Bu dersin sonunda koşullarla dolu bir personel rehberi hakkında TRUE, FALSE ya da NOT GIVEN’a karar verebilecek ve bir hizmet politikasıyla ilgili kısa soruları kelime sınırı içinde cevaplayabileceksin.","fa":"بعد از این درس می‌توانی درباره‌ی یک راهنمای کارکنان که پر از شرط است بین ⁨TRUE⁩، ⁨FALSE⁩ و ⁨NOT GIVEN⁩ تصمیم بگیری و به سؤال‌های کوتاه درباره‌ی یک آیین‌نامه‌ی خدمات در محدوده‌ی سقف کلمه جواب بدهی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"13"},{"label":{"en":"Texts","tr":"Metin","fa":"متن"},"value":"2"},{"label":{"en":"Short answers","tr":"Kısa cevaplar","fa":"جواب کوتاه"},"value":{"en":"3 words / number","tr":"3 kelime / sayı","fa":"۳ کلمه / عدد"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ زمینه"},"head":{"en":"This exam: a new staff rota and a service policy","tr":"Bu sınav: yeni bir vardiya çizelgesi ve bir hizmet politikası","fa":"این آزمون: برنامه‌ی شیفت تازه و آیین‌نامه‌ی خدمات به مشتری"},"intro":{"en":"GT Section 2 is about work. Staff guides and workplace policies are among its most frequent texts; here a supermarket explains a new shift system to its staff and sets out how to deal with refunds and complaints.","tr":"GT Section 2 iş hayatıyla ilgilidir. Personel rehberleri ve iş yeri politikaları en sık çıkan metinleri arasındadır; burada bir süpermarket yeni vardiya sistemini personeline anlatıyor ve iadelerle şikâyetlerin nasıl ele alınacağını belirtiyor.","fa":"⁨GT Section 2⁩ درباره‌ی کار است. راهنمای کارکنان و آیین‌نامه‌های محل کار از پرتکرارترین متن‌هایش‌اند؛ این‌جا یک سوپرمارکت سیستم تازه‌ی شیفت را برای کارکنانش توضیح می‌دهد و می‌گوید با پس گرفتن کالا و شکایت‌ها چطور باید برخورد کرد."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب در آن‌هاست"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x11-r2gt-ctx","exam":true,"patterns":["GT2-policy","GT2-business","PARA-rules"],"often":{"pattern":"GT2-policy","n":11,"of":55,"label":{"en":"Comes up often in the real exam: 11 of the last 55 texts","tr":"Gerçek sınavda sık çıkar: son 55 metnin 11’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۱ متن از ۵۵ متنِ اخیر"}},"title":{"en":"A staff rota and a customer-service policy","tr":"Bir vardiya çizelgesi ve bir müşteri hizmetleri politikası","fa":"برنامه‌ی شیفت و آیین‌نامه‌ی خدمات مشتری"},"asks":{"en":"Two texts for the staff of one company: a guide to a new shift system (patterns, publishing, swaps, breaks, requests, night work) and a policy for the service desk (refunds, faulty goods, complaints, vouchers). TRUE/FALSE/NOT GIVEN on the first, short answers on the second.","tr":"Aynı şirketin çalışanları için iki metin: yeni bir vardiya sistemi rehberi (düzen, yayınlanma, değişim, molalar, talepler, gece çalışması) ve müşteri hizmetleri masası için bir politika (iadeler, kusurlu ürünler, şikâyetler, kuponlar). Birincisinde TRUE/FALSE/NOT GIVEN, ikincisinde kısa cevaplar.","fa":"دو متن برای کارکنان یک شرکت: راهنمای یک سیستم شیفت تازه (الگوی شیفت، اعلام برنامه، جابه‌جایی، استراحت، درخواست‌ها، کار شبانه) و آیین‌نامه‌ی میز خدمات مشتری (پس دادن پول، کالای معیوب، شکایت، کوپن). در اولی ⁨TRUE/FALSE/NOT GIVEN⁩ و در دومی جواب کوتاه."},"fields":["Shift patterns","Publishing the rota","Swapping shifts","Breaks","Requests","Night work","Refunds and exchanges","Faulty goods","Complaints"],"words":[{"a":"change from week to week","b":"rotate over a four-week cycle","tr":"haftadan haftaya değişmek","fa":"هفته به هفته عوض شدن"},{"a":"three weeks or more","b":"at least three weeks","tr":"üç hafta ya da daha fazla","fa":"سه هفته یا بیشتر"},{"a":"only if","b":"provided / on condition that","tr":"yalnızca ... ise","fa":"فقط اگر"},{"a":"agree to","b":"approve / sign off","tr":"onay vermek","fa":"موافقت کردن"},{"a":"one after another","b":"in a row / consecutive","tr":"art arda","fa":"پشت سر هم"},{"a":"not paid","b":"unpaid","tr":"ücreti ödenmeyen","fa":"بدون حقوق"},{"a":"can choose","b":"voluntary / optional","tr":"seçebilir","fa":"می‌تواند انتخاب کند"},{"a":"looked at","b":"considered","tr":"incelenmiş","fa":"بررسی‌شده"},{"a":"after buying","b":"from the date of purchase","tr":"satın aldıktan sonra","fa":"بعد از خرید"},{"a":"does not work properly","b":"faulty","tr":"düzgün çalışmıyor","fa":"درست کار نمی‌کند"},{"a":"immediately","b":"on the spot / there and then","tr":"hemen, oracıkta","fa":"فوراً"},{"a":"solved","b":"settled / dealt with","tr":"çözülmüş","fa":"حل‌شده"}],"traps":[{"en":"A rule with \"provided\" or \"only if\" has a condition. A statement that drops the condition (\"any colleague\", \"at any time\") is FALSE.","tr":"\"Provided\" ya da \"only if\" içeren bir kuralın bir koşulu vardır. Koşulu atan bir ifade (\"herhangi bir iş arkadaşı\", \"istediğin zaman\") FALSE’tur.","fa":"قانونی که «⁨provided⁩» یا «⁨only if⁩» دارد شرط دارد. جمله‌ای که شرط را حذف کند («هر همکاری»، «هر وقت») ⁨FALSE⁩ است."},{"en":"\"Will be considered\" is not \"will be accepted\". A promise to look at requests says nothing about how many succeed: NOT GIVEN.","tr":"\"Değerlendirilecek\", \"kabul edilecek\" demek değildir. Talepleri incelemeye dair bir söz, kaçının kabul edildiği hakkında bir şey söylemez: NOT GIVEN.","fa":"«بررسی می‌شود» یعنی «پذیرفته می‌شود» نیست. قولِ بررسی درخواست‌ها چیزی درباره‌ی تعداد درخواست‌های پذیرفته‌شده نمی‌گوید: ⁨NOT GIVEN⁩."},{"en":"Short answers: \"a\" and \"the\" count as words. Leave them out when the answer would go over the limit.","tr":"Kısa cevaplar: \"a\" ve \"the\" kelime sayılır. Cevap sınırı aşacaksa onları çıkar.","fa":"جواب‌های کوتاه: «⁨a⁩» و «⁨the⁩» هم کلمه حساب می‌شوند. اگر جواب از سقف رد می‌شود، حذفشان کن."}],"example":{"text":"\"Staff may leave early on Fridays, provided their manager agrees.\"","item":"Statement: All staff may leave early on Fridays without asking.  (TRUE / FALSE / NOT GIVEN)","answer":"FALSE","why":{"en":"\"Provided their manager agrees\" is a condition; \"without asking\" contradicts it.","tr":"\"Müdürleri kabul ederse\" bir koşuldur; \"sormadan\" bununla çelişir.","fa":"«به شرطی که مدیرشان موافقت کند» یک شرط است؛ «بدون اجازه گرفتن» با آن تناقض دارد."}}},{"id":"GT2-policy","ctx":["GT2-policy"],"title":{"en":"Workplace policies and conditions","tr":"İş yeri politikaları ve çalışma koşulları","fa":"آیین‌نامه‌ها و شرایط محیط کار"},"asks":{"en":"A page from a staff handbook: parking, dress code, leave, absence, benefits or the complaints procedure. Questions test what staff must do, by when, and who they tell.","tr":"Bir personel el kitabından bir sayfa: otopark, kıyafet kuralı, izin, devamsızlık, yan haklar ya da şikâyet prosedürü. Sorular personelin ne yapması gerektiğini, ne zamana kadar ve kime haber vereceğini sınar.","fa":"صفحه‌ای از راهنمای کارکنان: پارکینگ، قانون پوشش، مرخصی، غیبت، مزایا یا روند رسیدگی به شکایت. سؤال‌ها می‌سنجند کارکنان چه باید بکنند، تا کی و به چه کسی خبر بدهند."},"fields":["Staff must inform their ___ before 9 a.m. if they are ill.","Holiday requests need ___ weeks’ notice.","Parking permits are issued by ___.","Jeans may be worn on ___."],"words":[{"a":"entitled to","b":"have the right to","tr":"... hakkı olmak","fa":"حق داشتن"},{"a":"annual leave","b":"holiday","tr":"yıllık izin","fa":"مرخصی سالانه"},{"a":"notice","b":"warning in advance","tr":"önceden haber","fa":"اطلاع قبلی"},{"a":"sick leave","b":"time off when you are ill","tr":"hastalık izni","fa":"مرخصی استعلاجی"},{"a":"permit","b":"an official permission card","tr":"izin kartı","fa":"مجوز"},{"a":"dress code","b":"rules about clothes","tr":"kıyafet kuralları","fa":"قانون پوشش"},{"a":"casual","b":"informal / relaxed","tr":"rahat, gündelik","fa":"غیررسمی"},{"a":"grievance","b":"a formal complaint","tr":"resmî şikâyet","fa":"شکایت رسمی"},{"a":"approve","b":"agree to / sign off","tr":"onaylamak","fa":"تأیید کردن"},{"a":"allowance","b":"money paid for something","tr":"ödenek","fa":"کمک‌هزینه"},{"a":"probation","b":"a trial period","tr":"deneme süresi","fa":"دوره‌ی آزمایشی"},{"a":"in writing","b":"by email or letter","tr":"yazılı olarak","fa":"به‌صورت کتبی"}],"traps":[{"en":"Who to tell: \"your line manager\" and \"HR\" are often named for different steps.","tr":"Kime haber verilir: \"bağlı olduğun yönetici\" ve \"İK\" çoğu zaman farklı adımlar için geçer.","fa":"به چه کسی خبر بدهی: «مدیر مستقیم» و «منابع انسانی» اغلب برای مرحله‌های مختلف نام برده می‌شوند."},{"en":"Periods: \"two weeks’ notice\" and \"within two weeks\" mean different things.","tr":"Süreler: \"iki hafta önceden haber\" ile \"iki hafta içinde\" farklı şeylerdir.","fa":"مدت‌ها: «دو هفته اطلاع قبلی» با «ظرف دو هفته» فرق دارد."}],"example":{"text":"If you cannot come to work because of illness, phone your line manager before 9 a.m. on the first day. HR only needs to be told if the absence lasts more than five working days.","item":"Staff who are ill must first contact their ___.   (NO MORE THAN TWO WORDS)","answer":"line manager","why":{"en":"The line manager is told first; HR only after five working days.","tr":"Önce bağlı olunan yöneticiye haber verilir; İK’ya ancak beş iş gününden sonra.","fa":"اول به مدیر مستقیم خبر می‌دهی؛ به منابع انسانی فقط بعد از پنج روز کاری."}},"track":"gt","general":true,"patterns":["GT2-policy"],"often":{"pattern":"GT2-policy","n":11,"of":55,"label":{"en":"Comes up often in the real exam: 11 of the last 55 texts","tr":"Gerçek sınavda sık çıkar: son 55 metnin 11’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۱ متن از ۵۵ متنِ اخیر"}}},{"id":"GT2-business","ctx":["GT2-business"],"title":{"en":"Running a team or a small business","tr":"Bir ekibi ya da küçük bir işletmeyi yönetmek","fa":"اداره‌ی یک تیم یا یک کسب‌وکار کوچک"},"asks":{"en":"Workplace guides on meetings, projects, delegation, marketing, flexible working or types of training. Sentence and note completion test the advice and the steps.","tr":"Toplantılar, projeler, görev devri, pazarlama, esnek çalışma ya da eğitim türleri üzerine iş yeri rehberleri. Cümle ve not tamamlama tavsiyeleri ve adımları sınar.","fa":"راهنماهای محیط کار درباره‌ی جلسه، پروژه، واگذاری کار، بازاریابی، کار منعطف یا انواع آموزش. کامل کردن جمله و یادداشت توصیه‌ها و مرحله‌ها را می‌سنجد."},"fields":["Before a meeting, send the ___ to everyone.","Give tasks to staff who can do them ___.","Flexible hours must be agreed with your ___.","Training: on the job · external course · online"],"words":[{"a":"agenda","b":"list of points for the meeting","tr":"gündem","fa":"دستور جلسه"},{"a":"delegate","b":"give a task to someone else","tr":"görev devretmek","fa":"واگذار کردن"},{"a":"deadline","b":"the date it must be done by","tr":"son tarih","fa":"مهلت"},{"a":"budget","b":"the money available","tr":"bütçe","fa":"بودجه"},{"a":"priorities","b":"what matters most","tr":"öncelikler","fa":"اولویت‌ها"},{"a":"minutes","b":"written record of a meeting","tr":"toplantı tutanağı","fa":"صورت‌جلسه"},{"a":"colleague","b":"co-worker","tr":"iş arkadaşı","fa":"همکار"},{"a":"line manager","b":"the person you report to","tr":"bağlı olduğun yönetici","fa":"مدیر مستقیم"},{"a":"flexible hours","b":"choose when you start and finish","tr":"esnek çalışma saatleri","fa":"ساعت کاری منعطف"},{"a":"client","b":"customer","tr":"müşteri","fa":"مشتری"},{"a":"promote","b":"advertise / market","tr":"tanıtmak","fa":"تبلیغ کردن"},{"a":"progress","b":"how far the work has got","tr":"ilerleme","fa":"پیشرفت"}],"traps":[{"en":"The sentence to complete is a paraphrase; the gap word is copied from the text.","tr":"Tamamlanacak cümle başka sözcüklerle yazılmıştır; boşluktaki kelime metinden kopyalanır.","fa":"جمله‌ای که کامل می‌کنی با کلمه‌های دیگر نوشته شده؛ کلمه‌ی جای خالی را از متن کپی کن."},{"en":"Lists of advice: the question asks about one step (\"before the meeting\"); the text lists several.","tr":"Tavsiye listeleri: soru tek bir adımı sorar (\"toplantıdan önce\"); metin birkaçını sıralar.","fa":"فهرست توصیه‌ها: سؤال درباره‌ی یک مرحله است («قبل از جلسه»)؛ متن چند مرحله را می‌شمارد."}],"example":{"text":"Circulate the minutes within 24 hours, while decisions are still fresh. Each action point should name one person, not a whole department.","item":"Sentence: Each action point should name a single ___.   (ONE WORD ONLY)","answer":"person","why":{"en":"\"Name one person, not a whole department\": a single person.","tr":"\"Bütün bir bölümü değil, tek bir kişiyi yaz\": a single person.","fa":"«یک نفر را نام ببر، نه کل یک بخش را»: a single person."}},"track":"gt","general":true,"patterns":["GT2-business"],"often":{"pattern":"GT2-business","n":16,"of":55,"label":{"en":"Comes up often in the real exam: 16 of the last 55 texts","tr":"Gerçek sınavda sık çıkar: son 55 metnin 16’sında","fa":"در آزمون واقعی زیاد می‌آید: در ۱۶ متن از ۵۵ متنِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Eight statements, five short answers","tr":"Sekiz ifade, beş kısa cevap","fa":"هشت جمله، پنج جواب کوتاه"},"body":{"en":"Questions 15-22: TRUE, FALSE or NOT GIVEN on the staff guide. Questions 23-27: answer with NO MORE THAN THREE WORDS AND/OR A NUMBER from the service policy. Both sets follow the order of their text.","tr":"Soru 15-22: personel rehberi hakkında TRUE, FALSE ya da NOT GIVEN. Soru 23-27: hizmet politikasından NO MORE THAN THREE WORDS AND/OR A NUMBER ile cevapla. İki grup da kendi metninin sırasını izler.","fa":"سؤال‌های ۱۵ تا ۲۲: ⁨TRUE⁩، ⁨FALSE⁩ یا ⁨NOT GIVEN⁩ درباره‌ی راهنمای کارکنان. سؤال‌های ۲۳ تا ۲۷: با ⁨NO MORE THAN THREE WORDS AND/OR A NUMBER⁩ از آیین‌نامه‌ی خدمات جواب بده. هر دو گروه به ترتیب متن خودشان‌اند."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps","tr":"Dört adım","fa":"چهار قدم"},"steps":[{"en":"Use the headings (Swapping shifts, Breaks, Requests) to find the part of the guide each statement is about.","tr":"Her ifadenin rehberin hangi kısmıyla ilgili olduğunu bulmak için başlıkları (Swapping shifts, Breaks, Requests) kullan.","fa":"با کمک عنوان‌ها (⁨Swapping shifts⁩، ⁨Breaks⁩، ⁨Requests⁩) پیدا کن هر جمله درباره‌ی کدام بخش راهنماست."},{"en":"Check every condition in the rule: who, when, how long before, provided what.","tr":"Kuraldaki her koşulu kontrol et: kim, ne zaman, ne kadar önce, hangi şartla?","fa":"همه‌ی شرط‌های قانون را چک کن: چه کسی، کی، چقدر قبل، با چه شرطی."},{"en":"For short answers, find the fact, copy the shortest group of words that answers the question, then count them.","tr":"Kısa cevaplar için bilgiyi bul, soruyu cevaplayan en kısa kelime grubunu kopyala, sonra kelimeleri say.","fa":"برای جواب کوتاه، نکته را پیدا کن، کوتاه‌ترین گروه کلمه‌ای را که جواب سؤال است کپی کن و بعد کلمه‌ها را بشمار."},{"en":"You can write numbers as figures, but keep the word that goes with them: 28 days, not 28.","tr":"Sayıları rakamla yazabilirsin ama yanındaki kelimeyi koru: 28 değil, 28 days.","fa":"عددها را می‌توانی با رقم بنویسی، اما کلمه‌ی همراهشان را نگه دار: ⁨28 days⁩، نه ⁨28⁩."}],"wrong":"What must staff bring? → a signed letter from their manager","right":"What must staff bring? → signed letter","tip":{"en":"Why it works: the shortest group of words is usually enough, and it never breaks the limit. \"A signed letter from their manager\" is six words, so it scores nothing even with the right fact. Persian and Turkish have no word like \"the\", so it is easy to forget that \"a\" and \"the\" are counted too.","tr":"Neden işe yarar: En kısa kelime grubu genelde yeterlidir ve sınırı asla aşmaz. \"A signed letter from their manager\" altı kelimedir; bilgi doğru olsa bile puan getirmez. Türkçede \"the\" gibi bir kelime olmadığı için \"a\" ve \"the\"nin de sayıldığını unutmak kolaydır.","fa":"این روش به کارت می‌آید، چون کوتاه‌ترین گروه کلمه معمولاً کافی است و هیچ‌وقت از سقف رد نمی‌شود. «⁨a signed letter from their manager⁩» شش کلمه است، پس حتی با نکته‌ی درست هم نمره‌ای نمی‌گیرد. در فارسی کلمه‌ای مثل «⁨the⁩» نداریم، برای همین راحت یادمان می‌رود که «⁨a⁩» و «⁨the⁩» هم شمرده می‌شوند."}},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Conditions and promises","tr":"Koşullar ve sözler","fa":"شرط‌ها و قول‌ها"},"table":{"headers":{"en":["The text","The statement","Answer"],"tr":["Metin","İfade","Cevap"],"fa":["متن","جمله","جواب"]},"rows":[["may park here, provided they display a permit","anyone may park here","FALSE"],["each application will be considered","most applications succeed","NOT GIVEN"],["overtime will remain optional","staff can refuse overtime","TRUE"]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One statement, step by step","tr":"Bir ifade, adım adım","fa":"یک جمله، قدم به قدم"},"instruction":"Do the following statements agree with the information given in the text?","text":"\"Holiday requests must be made at least four weeks in advance. Requests for August are dealt with in the order they arrive.\"","item":"Statement: Staff can book a week off in August two weeks before it starts.","answer":"FALSE","walk":[{"en":"Find the place: holiday requests.","tr":"Yeri bul: izin talepleri.","fa":"جایش را پیدا کن: درخواست مرخصی."},{"en":"The rule: at least four weeks in advance, for every month, August included.","tr":"Kural: Ağustos da dâhil her ay için en az dört hafta önceden.","fa":"قانون: برای همه‌ی ماه‌ها، از جمله اوت، دست‌کم چهار هفته زودتر."},{"en":"Two weeks breaks the rule: FALSE.","tr":"İki hafta kuralı çiğniyor: FALSE.","fa":"دو هفته خلاف این قانون است: ⁨FALSE⁩."}]},"quick":{"prompt":"Text: \"Staff who work on a public holiday receive an extra day off.\" Statement: \"Staff are paid double for working on a public holiday.\" TRUE, FALSE or NOT GIVEN?","options":["TRUE","FALSE","NOT GIVEN"],"correct":2,"why":{"en":"The text mentions an extra day off, but says nothing about the rate of pay.","tr":"Metin fazladan bir izin gününden söz ediyor ama ücret hakkında bir şey söylemiyor.","fa":"متن از یک روز مرخصی اضافه حرف می‌زند، اما درباره‌ی میزان دستمزد چیزی نمی‌گوید."}},"remember":{"en":"Check every condition before you answer TRUE, and keep each short answer to the fewest words that work. Result: you can now spot a missing condition in a statement and write short answers inside the limit.","tr":"TRUE demeden önce her koşulu kontrol et ve her kısa cevabı işe yarayan en az kelimeyle yaz. Sonuç: Artık bir ifadede eksik koşulu fark edebilir, kısa cevapları sınır içinde yazabilirsin.","fa":"قبل از اینکه ⁨TRUE⁩ بزنی همه‌ی شرط‌ها را چک کن و هر جواب کوتاه را با کمترین کلمه‌ی ممکن بنویس. نتیجه: حالا می‌توانی شرطِ جاافتاده در یک جمله را ببینی و جواب‌های کوتاه را در سقف کلمه بنویسی."},"hook":{"en":"Section 2 here is a staff guide and a service policy, full of conditions. The main idea: a statement that drops a condition is FALSE, and a short answer must stay inside the limit.","tr":"Buradaki Section 2 koşullarla dolu bir personel rehberi ve bir hizmet politikasıdır. Ana fikir: Bir koşulu atan ifade FALSE’tur, kısa cevap da sınırın içinde kalmalıdır.","fa":"این ⁨Section 2⁩ یک راهنمای کارکنان و یک آیین‌نامه‌ی خدمات است، پر از شرط. جمله‌ای که شرطی را جا بیندازد ⁨FALSE⁩ است و جواب کوتاه باید در سقف کلمه بماند."},"type":"explain","id":"c-x11-r2-e-gt","course":"ielts-exams","exam":"exam-11","unit":"x11-r2"},"drill":{"type":"drill","skill":"reading","part":"General Training Reading Section 2","title":{"en":"A new staff rota and a service policy","tr":"Yeni bir vardiya çizelgesi ve bir hizmet politikası","fa":"برنامه‌ی شیفت تازه و آیین‌نامه‌ی خدمات"},"timed":20,"ctx":["GT2-policy","GT2-business"],"texts":[{"title":"Marlow's Supermarkets: the new staff rota","kind":"staff guide","body":"From Monday 3 March, every Marlow's store will move to a new rota system. This guide explains the main changes. If anything is unclear, please speak to your store manager.\n\nShift patterns\nAt present, most staff work fixed shifts on the same days each week. Under the new system, shifts will rotate over a four-week cycle, so that early starts, late finishes and weekend work are shared more evenly across each team. Full-time staff will still work an average of 37.5 hours a week, although the number of hours in a single week may vary.\n\nPublishing the rota\nEach rota will be posted on the staff noticeboard and on the staff app at least three weeks before it begins. Once a rota has been published, it will only be changed in an emergency.\n\nSwapping shifts\nYou may swap a shift with a colleague who does the same job, provided you have both completed the same training. Swaps must be requested on the staff app at least 48 hours before the shift begins and approved by a supervisor. A swap will not be approved if it would mean either of you working more than six days in a row.\n\nBreaks\nEvery shift of six hours or more includes an unpaid break of 30 minutes. Staff working more than eight hours will also receive an extra 15-minute break, which is paid.\n\nRequests\nIf you have regular commitments, such as caring for a relative or attending a course, you can ask for certain shifts to be avoided. Requests should be made in writing to your store manager. We cannot promise that every request will be accepted, but each one will be considered fairly.\n\nNight work\nNight shifts in our warehouses will remain voluntary. Staff who choose to work them will continue to receive a higher hourly rate."},{"title":"Customer service desk: refunds, exchanges and complaints","kind":"service policy","body":"At Marlow's, we want every customer to leave the store satisfied. Staff at the customer service desk should follow this policy when dealing with returns and complaints.\n\nRefunds and exchanges\nMost items can be returned within 28 days of purchase for a full refund, provided the customer has a receipt or the payment card that was used. Without either of these, staff may offer a store credit note, but not a cash refund. Fresh food can only be returned on the day it was bought, unless it is found to be past its use-by date. Items bought in a sale cannot be refunded, but they can be exchanged for another item of the same price.\n\nFaulty goods\nIf an item is faulty, the customer is entitled to a refund even after 28 days, up to six months from the date of purchase. Electrical items must be checked by a supervisor before any refund is given.\n\nComplaints\nMost complaints can be settled on the spot. Listen carefully, apologise and explain what you are able to do. If the customer is still not satisfied, call the duty manager. Never argue with a customer, and do not promise anything that you cannot provide. A complaint that cannot be settled in the store should be recorded on a complaint form, and the customer should be given a reference number. Head office aims to reply within ten working days.\n\nGoodwill vouchers\nDuty managers may offer a voucher worth up to £10 to a customer who has had a serious problem, such as a long wait at the tills."}],"groups":[{"text":0,"instruction":"Questions 15-22. Do the following statements agree with the information given in the text? Write TRUE if the statement agrees with the information, FALSE if the statement contradicts the information, NOT GIVEN if there is no information on this.","qtype":"tfng","questions":[{"n":15,"kind":"tfng","prompt":"The new rota will start on the same day in all stores.","correct":"TRUE","evidence":"From Monday 3 March, every Marlow's store will move to a new rota system","why":{"en":"\"From Monday 3 March, every Marlow's store will move\" to the new system: the same day in all stores.","tr":"\"3 Mart Pazartesi’den itibaren her Marlow's mağazası\" yeni sisteme geçecek: tüm mağazalarda aynı gün.","fa":"«از دوشنبه ۳ مارس همه‌ی فروشگاه‌های ⁨Marlow's⁩» به سیستم تازه می‌روند: یعنی در همه‌ی فروشگاه‌ها همان روز."},"trap":["TR-paraphrase"]},{"n":16,"kind":"tfng","prompt":"Under the new system, staff will normally work the same days every week.","correct":"FALSE","evidence":"shifts will rotate over a four-week cycle","why":{"en":"Shifts \"will rotate over a four-week cycle\"; fixed days belong to the old system.","tr":"Vardiyalar \"dört haftalık bir döngüde dönüşümlü olacak\"; sabit günler eski sisteme ait.","fa":"شیفت‌ها «در یک دوره‌ی چهارهفته‌ای چرخشی می‌شوند»؛ روزهای ثابت مال سیستم قدیمی است."},"trap":["TR-NGvsF","TR-samewords"]},{"n":17,"kind":"tfng","prompt":"The new system was introduced because staff asked for it.","correct":"NOT GIVEN","evidence":"so that early starts, late finishes and weekend work are shared more evenly","why":{"en":"The guide gives the aim (sharing shifts more evenly), but not who asked for the change.","tr":"Rehber amacı veriyor (vardiyaları daha eşit paylaştırmak) ama değişikliği kimin istediğini söylemiyor.","fa":"راهنما هدف را می‌گوید (تقسیم عادلانه‌تر شیفت‌ها)، اما نمی‌گوید چه کسی این تغییر را خواسته."},"trap":["TR-NGvsF"]},{"n":18,"kind":"tfng","prompt":"Staff will be able to see each rota three weeks or more before it starts.","correct":"TRUE","evidence":"at least three weeks before it begins","why":{"en":"\"At least three weeks before it begins\" = three weeks or more.","tr":"\"Başlamadan en az üç hafta önce\" = üç hafta ya da daha fazla.","fa":"«دست‌کم سه هفته قبل از شروعش» یعنی سه هفته یا بیشتر."},"trap":["TR-paraphrase"]},{"n":19,"kind":"tfng","prompt":"Staff may swap a shift with any colleague who works in the same store.","correct":"FALSE","evidence":"a colleague who does the same job, provided you have both completed the same training","why":{"en":"Swaps are only with \"a colleague who does the same job, provided you have both completed the same training\".","tr":"Vardiya değişimi yalnızca \"aynı işi yapan ve aynı eğitimi tamamlamış bir iş arkadaşıyla\" yapılabilir.","fa":"جابه‌جایی فقط با «همکاری که همان کار را می‌کند، به شرطی که هر دو همان آموزش را دیده باشید» ممکن است."},"trap":["TR-NGvsF"]},{"n":20,"kind":"tfng","prompt":"A supervisor must agree to a shift swap.","correct":"TRUE","evidence":"approved by a supervisor","why":{"en":"Swaps must be \"approved by a supervisor\": agree to = approve.","tr":"Vardiya değişimleri \"bir amir tarafından onaylanmalı\": agree to = approve.","fa":"جابه‌جایی‌ها باید «تأیید سرپرست» را بگیرند: ⁨agree to⁩ یعنی ⁨approve⁩."},"trap":["TR-paraphrase"]},{"n":21,"kind":"tfng","prompt":"Most requests to avoid particular shifts are accepted.","correct":"NOT GIVEN","evidence":"each one will be considered fairly","why":{"en":"Requests \"will be considered fairly\", but the guide does not say how many are accepted.","tr":"Talepler \"adil biçimde değerlendirilecek\" ama rehber kaçının kabul edildiğini söylemiyor.","fa":"درخواست‌ها «منصفانه بررسی می‌شوند»، اما راهنما نمی‌گوید چندتایشان پذیرفته می‌شوند."},"trap":["TR-NGvsF","TR-hedge"]},{"n":22,"kind":"tfng","prompt":"Staff can be required to work night shifts in the warehouses.","correct":"FALSE","evidence":"Night shifts in our warehouses will remain voluntary","why":{"en":"Night shifts \"will remain voluntary\", so staff cannot be made to work them.","tr":"Gece vardiyaları \"gönüllü olmaya devam edecek\"; yani personel bunlara zorlanamaz.","fa":"شیفت‌های شب «داوطلبانه می‌مانند»، پس کسی را نمی‌شود مجبور کرد."},"trap":["TR-NGvsF"]}]},{"text":1,"instruction":"Questions 23-27. Answer the questions below. Choose NO MORE THAN THREE WORDS AND/OR A NUMBER from the text for each answer.","qtype":"short-answer","questions":[{"n":23,"kind":"gap","prompt":"Apart from a receipt, what can a customer show to get a full refund? ___","accept":["payment card","the payment card"],"limit":3,"evidence":"a receipt or the payment card that was used","why":{"en":"\"A receipt or the payment card that was used\". \"The payment card that was used\" is too long; \"payment card\" is enough.","tr":"\"Bir fiş ya da kullanılan ödeme kartı\". \"The payment card that was used\" çok uzun; \"payment card\" yeterli.","fa":"«رسید یا کارت بانکی‌ای که با آن پرداخت شده». «⁨the payment card that was used⁩» زیادی بلند است؛ «⁨payment card⁩» کافی است."},"trap":["TR-limit","TR-paraphrase"]},{"n":24,"kind":"gap","prompt":"What may staff offer a customer who has neither a receipt nor a payment card? ___","accept":["store credit note","credit note","a credit note"],"limit":3,"evidence":"staff may offer a store credit note","why":{"en":"\"Staff may offer a store credit note, but not a cash refund\". \"A store credit note\" is four words, so leave out \"a\".","tr":"\"Personel mağazada geçerli bir alışveriş çeki verebilir ama nakit iade yapamaz\". \"A store credit note\" dört kelimedir; \"a\"yı çıkar.","fa":"«کارمندها می‌توانند بن خریدِ فروشگاه بدهند، اما پول نقد پس نمی‌دهند». «⁨a store credit note⁩» چهار کلمه است، پس «⁨a⁩» را ننویس."},"trap":["TR-limit"]},{"n":25,"kind":"gap","prompt":"For how long after purchase can a customer get a refund for a faulty item? ___","accept":["six months","6 months"],"limit":3,"evidence":"up to six months from the date of purchase","why":{"en":"\"Up to six months from the date of purchase\"; 28 days is the limit for items that are not faulty.","tr":"\"Satın alma tarihinden itibaren altı aya kadar\"; 28 gün, kusurlu olmayan ürünler için sınırdır.","fa":"«تا شش ماه از تاریخ خرید»؛ ۲۸ روز مهلتِ کالاهای سالم است."},"trap":["TR-paraphrase","TR-samewords"]},{"n":26,"kind":"gap","prompt":"Who must check an electrical item before it is refunded? ___","accept":["supervisor","a supervisor"],"limit":3,"evidence":"must be checked by a supervisor","why":{"en":"Electrical items \"must be checked by a supervisor\". The duty manager deals with complaints, not with this check.","tr":"Elektrikli ürünler \"bir amir tarafından kontrol edilmeli\". Nöbetçi müdür bu kontrolle değil, şikâyetlerle ilgilenir.","fa":"وسایل برقی «باید سرپرست بررسی‌شان کند». مدیر شیفت به شکایت‌ها می‌رسد، نه به این بررسی."},"trap":["TR-paraphrase","TR-samewords"]},{"n":27,"kind":"gap","prompt":"What should a customer be given when their complaint is recorded on a form? ___","accept":["reference number","a reference number"],"limit":3,"evidence":"the customer should be given a reference number","why":{"en":"\"The customer should be given a reference number\".","tr":"\"Müşteriye bir referans numarası verilmeli\".","fa":"«باید به مشتری یک کد پیگیری داده شود»."},"trap":["TR-paraphrase"]}]}],"id":"c-x11-r2-d-gt","course":"ielts-exams","exam":"exam-11","unit":"x11-r2"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"Night shifts will remain voluntary.\" Voluntary means...","options":["paid at a higher rate","done only by choice","only for warehouse staff"],"correct":1,"why":{"en":"Voluntary = you choose whether to do it; no one can make you.","tr":"Voluntary = yapıp yapmamayı sen seçersin; kimse seni zorlayamaz.","fa":"⁨voluntary⁩ یعنی خودت انتخاب می‌کنی انجامش بدهی یا نه؛ کسی مجبورت نمی‌کند."}},{"tests":"paraphrase","point":1,"prompt":"A statement says \"three weeks or more before\". Which words in a text mean the same?","options":["at least three weeks before","within three weeks of","no later than three weeks after"],"correct":0,"why":{"en":"At least three weeks = three weeks or more.","tr":"At least three weeks = üç hafta ya da daha fazla.","fa":"⁨at least three weeks⁩ یعنی سه هفته یا بیشتر."}},{"tests":"method","point":2,"prompt":"\"Answer with NO MORE THAN THREE WORDS AND/OR A NUMBER.\" Which answer is acceptable?","options":["a store credit note","store credit note","a new store credit note"],"correct":1,"why":{"en":"\"Store credit note\" is three words; the others have four and five.","tr":"\"Store credit note\" üç kelimedir; diğerleri dört ve beş kelime.","fa":"«⁨store credit note⁩» سه کلمه است؛ بقیه چهار و پنج کلمه‌اند."}},{"tests":"trap","point":3,"prompt":"Text: \"Each request will be considered fairly.\" Statement: \"Most requests are accepted.\"","options":["NOT GIVEN","TRUE","FALSE"],"correct":0,"why":{"en":"Considering a request is not accepting it; the text gives no numbers.","tr":"Bir talebi değerlendirmek onu kabul etmek demek değildir; metin sayı vermiyor.","fa":"بررسی یک درخواست یعنی پذیرفتنش نیست؛ متن هیچ عددی نمی‌دهد."}}],"id":"c-x11-r2-x-gt","course":"ielts-exams","exam":"exam-11","unit":"x11-r2"}}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
